// --- Rute GET /api/members/profile ---
app.get('/api/members/profile', async (req, res) => {
  try {
    const userId = req.query.user_id || 1;
    let profileData = { ...mockMemberProfile };

    try {
      const [rows] = await db.execute(
        `SELECT u.id, u.full_name, u.email, u.member_id_number, u.membership_status,
                mp.headline, mp.company, mp.position, mp.specialization, mp.location,
                mp.phone, mp.linkedin_url, mp.bio, mp.avatar_url, mp.membership_tier,
                mp.membership_expiry, mp.open_for_collab
         FROM users_membership u
         LEFT JOIN member_profiles mp ON u.id = mp.user_id
         WHERE u.id = ?`,
        [userId]
      );
      if (rows.length > 0 && rows[0].full_name) {
        profileData = { ...profileData, ...rows[0] };
      }
    } catch (dbErr) {
      console.warn('DB query profile fallback:', dbErr.message);
    }

    res.status(200).json({ status: 'success', data: profileData });
  } catch (error) {
    console.error('Error fetching member profile:', error);
    res.status(500).json({ status: 'error', message: 'Gagal mengambil data profil anggota.' });
  }
});

// --- Rute PUT /api/members/profile ---
app.put('/api/members/profile', async (req, res) => {
  try {
    const userId = req.body.user_id || 1;
    const {
      full_name, headline, company, position,
      specialization, location, phone, linkedin_url, bio, open_for_collab
    } = req.body;

    // Update in-memory fallback
    mockMemberProfile = {
      ...mockMemberProfile,
      full_name: full_name || mockMemberProfile.full_name,
      headline: headline || mockMemberProfile.headline,
      company: company || mockMemberProfile.company,
      position: position || mockMemberProfile.position,
      specialization: specialization || mockMemberProfile.specialization,
      location: location || mockMemberProfile.location,
      phone: phone || mockMemberProfile.phone,
      linkedin_url: linkedin_url || mockMemberProfile.linkedin_url,
      bio: bio || mockMemberProfile.bio,
      open_for_collab: open_for_collab !== undefined ? Boolean(open_for_collab) : mockMemberProfile.open_for_collab
    };

    // Update MySQL jika terhubung
    try {
      if (full_name) {
        await db.execute('UPDATE users_membership SET full_name = ? WHERE id = ?', [full_name, userId]);
      }
      await db.execute(
        `INSERT INTO member_profiles (user_id, headline, company, position, specialization, location, phone, linkedin_url, bio, open_for_collab)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
         ON DUPLICATE KEY UPDATE
            headline = VALUES(headline),
            company = VALUES(company),
            position = VALUES(position),
            specialization = VALUES(specialization),
            location = VALUES(location),
            phone = VALUES(phone),
            linkedin_url = VALUES(linkedin_url),
            bio = VALUES(bio),
            open_for_collab = VALUES(open_for_collab)`,
        [userId, headline, company, position, specialization, location, phone, linkedin_url, bio, open_for_collab ? 1 : 0]
      );
    } catch (dbErr) {
      console.warn('DB update profile fallback:', dbErr.message);
    }

    res.status(200).json({
      status: 'success',
      message: 'Profil anggota berhasil diperbarui!',
      data: mockMemberProfile
    });
  } catch (error) {
    console.error('Error updating profile:', error);
    res.status(500).json({ status: 'error', message: 'Gagal memperbarui profil anggota.' });
  }
});

