app.get('/api/members/directory', async (req, res) => {
  try {
    const { search, location, specialization, position, collab_only } = req.query;

    let filtered = [...mockDirectoryMembers];

    if (search) {
      const q = search.toLowerCase();
      filtered = filtered.filter(m =>
        m.name.toLowerCase().includes(q) ||
        m.company.toLowerCase().includes(q) ||
        m.specialization.toLowerCase().includes(q) ||
        m.position.toLowerCase().includes(q) ||
        m.location.toLowerCase().includes(q)
      );
    }

    if (location && location !== 'Semua') {
      filtered = filtered.filter(m => m.location.toLowerCase().includes(location.toLowerCase()));
    }

    if (specialization && specialization !== 'Semua') {
      filtered = filtered.filter(m => m.specialization.toLowerCase().includes(specialization.toLowerCase()));
    }

    if (position && position !== 'Semua') {
      filtered = filtered.filter(m => m.position.toLowerCase().includes(position.toLowerCase()));
    }

    if (collab_only === 'true') {
      filtered = filtered.filter(m => m.open_for_collab === true);
    }

    res.status(200).json({
      status: 'success',
      total: filtered.length,
      data: filtered
    });
  } catch (error) {
    console.error('Error fetching directory:', error);
    res.status(500).json({ status: 'error', message: 'Gagal memuat direktori anggota.' });
  }
});

