app.get('/api/resources', async (req, res) => {
  try {
    const { category, search } = req.query;
    let list = [...mockResourceCenter];

    if (category && category !== 'Semua') {
      list = list.filter(r => r.category.toLowerCase() === category.toLowerCase());
    }

    if (search) {
      const q = search.toLowerCase();
      list = list.filter(r =>
        r.title.toLowerCase().includes(q) ||
        r.description.toLowerCase().includes(q) ||
        r.author.toLowerCase().includes(q)
      );
    }

    res.status(200).json({
      status: 'success',
      total: list.length,
      data: list
    });
  } catch (error) {
    console.error('Error fetching resources:', error);
    res.status(500).json({ status: 'error', message: 'Gagal mengambil data pusat sumber daya.' });
  }
});

// --- Rute POST /api/resources/:id/download (Simulasi Counter Unduh) ---
app.post('/api/resources/:id/download', (req, res) => {
  const resourceId = parseInt(req.params.id, 10);
  const resource = mockResourceCenter.find(r => r.id === resourceId);
  if (resource) {
    resource.downloads += 1;
    return res.status(200).json({ status: 'success', message: 'Unduhan dimulai', downloads: resource.downloads });
  }
  res.status(404).json({ status: 'error', message: 'Dokumen tidak ditemukan' });
});

// --- Rute GET /api/members/cpd/summary ---
// Mengambil ringkasan poin CPD anggota pada tahun berjalan (mock user_id = 1)
app.get('/api/members/cpd/summary', async (req, res) => {
  try {
    const userId = req.query.user_id || 1;
    const currentYear = new Date().getFullYear();
    let totalPoints = 0;

    try {
      const [rows] = await db.execute(
        `SELECT COALESCE(SUM(e.cpd_points), 0) AS total_points
         FROM event_registrations er
         JOIN events e ON er.event_id = e.event_id
         WHERE er.user_id = ?
           AND er.attendance_status = 'Attended'
           AND YEAR(e.event_date) = ?`,
        [userId, currentYear]
      );
      totalPoints = Number(rows[0]?.total_points || 0);
    } catch (dbError) {
      console.warn('Database offline/query fallback:', dbError.message);
      // Fallback data demo jika service MySQL lokal tidak aktif
      totalPoints = 25;
    }

    const targetPoints = 30;

    res.status(200).json({
      status: 'success',
      data: {
        user_id: Number(userId),
        year: currentYear,
        total_points: totalPoints,
        target_points: targetPoints
      }
    });
  } catch (error) {
    console.error('Error fetching CPD summary:', error);
    res.status(500).json({ status: 'error', message: 'Gagal mengambil data poin CPD.' });
  }
});

