336:         // 1. Fetch Berita
337:         async function fetchNews() {
338:             const container = document.getElementById('news-container');
339:             try {
340:                 const response = await fetch('/api/news');
341:                 if (!response.ok) throw new Error('Gagal memuat API');
342:                 
343:                 const result = await response.json();
344:                 const newsData = result.data;
345: 
346:                 if (newsData && newsData.length > 0) {
347:                     container.innerHTML = ''; // Clear loading
348:                     newsData.forEach(news => {
349:                         const card = `
350:                             <div class="api-card">
351:                                 <span class="api-badge">${news.category || 'Berita'}</span>
352:                                 <h4>${news.title}</h4>
353:                                 <p>${news.content.substring(0, 100)}...</p>
354:                                 <a href="#" class="api-link">Baca Selengkapnya →</a>
355:                             </div>
356:                         `;
357:                         container.innerHTML += card;
358:                     });
359:                 } else {
360:                     container.innerHTML = '<div class="loading-state">Belum ada berita yang dipublikasikan.</div>';
361:                 }
362:             } catch (error) {
363:                 console.error(error);
364:                 container.innerHTML = `
365:                     <div class="api-card" style="border: 1px dashed var(--border-color); box-shadow: none;">
366:                         <span class="api-badge">Simulasi UI</span>
367:                         <h4>API Belum Terhubung Sempurna</h4>
368:                         <p>Pastikan server Node.js dan Database MySQL berjalan untuk menampilkan data berita secara dinamis.</p>
369:                         <a href="#" class="api-link">Cek Koneksi Database →</a>
370:                     </div>
371:                 `;
372:             }
373:         }
374: 
