376:         async function fetchDownloads() {
377:             const container = document.getElementById('downloads-container');
378:             try {
379:                 // Untuk halaman publik, isLoggedIn = false
380:                 const response = await fetch('/api/downloads?isLoggedIn=false');
381:                 if (!response.ok) throw new Error('Gagal memuat API');
382:                 
383:                 const result = await response.json();
384:                 const docData = result.data;
385: 
386:                 if (docData && docData.length > 0) {
387:                     container.innerHTML = ''; // Clear loading
388:                     docData.forEach(doc => {
389:                         const card = `
390:                             <div class="api-card">
