403:                 console.error(error);
404:                 container.innerHTML = `
405:                     <div class="api-card" style="border: 1px dashed var(--border-color); box-shadow: none;">
406:                         <span class="api-badge" style="background: #f1f5f9; color: #475569;">📄 Simulasi UI</span>
