// --- 7. Rute POST /api/members/cpd/submit (Pengajuan Poin CPD Mandiri oleh Anggota) ---
app.post('/api/members/cpd/submit', upload.single('certificate_file'), async (req, res) => {
  try {
    const userId = Number(req.body.user_id) || 1;
    const { event_name, provider_name, event_date, score, claimed_points } = req.body;

    if (!event_name || !provider_name || !event_date || !claimed_points) {
      return res.status(400).json({
        status: 'error',
        message: 'Nama acara, penyelenggara, tanggal, dan poin yang diajukan wajib diisi.'
      });
    }

    const certUrl = req.file ? `/uploads/${req.file.filename}` : (req.body.certificate_url || '/uploads/sample-cert.pdf');
    const parsedScore = score ? parseFloat(score) : null;
    const parsedClaimed = parseInt(claimed_points, 10);

    const newSubmission = {
      submission_id: mockCpdSubmissions.length + 1,
      user_id: userId,
      user_name: mockMemberProfile.full_name || 'Budi Santoso',
      member_id_number: mockMemberProfile.member_id_number || 'APMA-2026-0892',
      event_name,
      provider_name,
      event_date,
      score: parsedScore,
      claimed_points: parsedClaimed,
      approved_points: 0,
      certificate_url: certUrl,
      status: 'Pending',
      admin_notes: null,
      submitted_at: new Date().toISOString().replace('T', ' ').substring(0, 19),
      approved_at: null,
      approved_by: null
    };

    mockCpdSubmissions.unshift(newSubmission);

    // Coba insert ke MySQL jika aktif
    try {
      await db.execute(
        `INSERT INTO cpd_submissions (user_id, event_name, provider_name, event_date, score, claimed_points, certificate_url, status)
         VALUES (?, ?, ?, ?, ?, ?, ?, 'Pending')`,
        [userId, event_name, provider_name, event_date, parsedScore, parsedClaimed, certUrl]
      );
    } catch (dbErr) {
      console.warn('DB cpd_submissions insert fallback:', dbErr.message);
    }

    res.status(201).json({
      status: 'success',
      message: 'Pengajuan poin CPD mandiri berhasil dikirim dan sedang menunggu verifikasi Admin.',
      data: newSubmission
    });
  } catch (error) {
    console.error('Error submitting CPD:', error);
    res.status(500).json({ status: 'error', message: 'Gagal memproses pengajuan poin CPD.' });
  }
});

// --- 8. Rute GET /api/members/cpd/submissions (Melihat Riwayat Pengajuan Anggota) ---
app.get('/api/members/cpd/submissions', async (req, res) => {
  try {
    const userId = Number(req.query.user_id) || 1;
    let submissions = mockCpdSubmissions.filter(s => s.user_id === userId);

    try {
      const [rows] = await db.execute(
        'SELECT * FROM cpd_submissions WHERE user_id = ? ORDER BY submitted_at DESC',
        [userId]
      );
      if (rows && rows.length > 0) submissions = rows;
    } catch (dbErr) {
      console.warn('DB cpd_submissions get fallback:', dbErr.message);
    }

    res.status(200).json({
      status: 'success',
      total: submissions.length,
      data: submissions
    });
  } catch (error) {
    console.error('Error fetching member submissions:', error);
    res.status(500).json({ status: 'error', message: 'Gagal memuat riwayat pengajuan CPD.' });
  }
});

// --- 9. Rute GET /api/admin/cpd/submissions (Daftar Pengajuan Masuk untuk Admin Review) ---
app.get('/api/admin/cpd/submissions', async (req, res) => {
  try {
    const { status } = req.query;
    let list = [...mockCpdSubmissions];

    if (status && status !== 'Semua') {
      list = list.filter(s => s.status.toLowerCase() === status.toLowerCase());
    }

    try {
      let query = `
        SELECT cs.*, u.full_name AS user_name, u.member_id_number, u.email
        FROM cpd_submissions cs
        JOIN users_membership u ON cs.user_id = u.id
      `;
      let params = [];
      if (status && status !== 'Semua') {
        query += ' WHERE cs.status = ?';
        params.push(status);
      }
      query += ' ORDER BY cs.submitted_at DESC';

      const [rows] = await db.execute(query, params);
      if (rows && rows.length > 0) list = rows;
    } catch (dbErr) {
      console.warn('DB admin submissions fallback:', dbErr.message);
    }

    res.status(200).json({
      status: 'success',
      total: list.length,
      data: list
    });
  } catch (error) {
    console.error('Error admin fetching submissions:', error);
    res.status(500).json({ status: 'error', message: 'Gagal memuat data pengajuan CPD admin.' });
  }
});

// --- 10. Rute PUT /api/admin/cpd/submissions/:id/review (Admin Menyetujui / Menolak Pengajuan) ---
app.put('/api/admin/cpd/submissions/:id/review', async (req, res) => {
  try {
    const submissionId = Number(req.params.id);
    const { status, approved_points, admin_notes, admin_id } = req.body;

    if (!['Approved', 'Rejected'].includes(status)) {
      return res.status(400).json({ status: 'error', message: 'Status harus Approved atau Rejected.' });
    }

    const sub = mockCpdSubmissions.find(s => s.submission_id === submissionId);
    if (!sub) {
      return res.status(404).json({ status: 'error', message: 'Data pengajuan tidak ditemukan.' });
    }

    const finalApprovedPoints = status === 'Approved' ? (parseInt(approved_points, 10) || sub.claimed_points) : 0;
    const nowStr = new Date().toISOString().replace('T', ' ').substring(0, 19);

    sub.status = status;
    sub.approved_points = finalApprovedPoints;
    sub.admin_notes = admin_notes || (status === 'Approved' ? 'Pengajuan disetujui admin.' : 'Pengajuan ditolak.');
    sub.approved_at = nowStr;
    sub.approved_by = admin_id || 99;

    // Coba update ke MySQL jika aktif
    try {
      await db.execute(
        `UPDATE cpd_submissions 
         SET status = ?, approved_points = ?, admin_notes = ?, approved_at = NOW(), approved_by = ?
         WHERE submission_id = ?`,
        [status, finalApprovedPoints, sub.admin_notes, sub.approved_by, submissionId]
      );
    } catch (dbErr) {
      console.warn('DB update review fallback:', dbErr.message);
    }

    res.status(200).json({
      status: 'success',
      message: `Pengajuan berhasil ${status === 'Approved' ? 'disetujui (+ ' + finalApprovedPoints + ' Poin CPD)' : 'ditolak'}.`,
      data: sub
    });
  } catch (error) {
    console.error('Error reviewing CPD:', error);
    res.status(500).json({ status: 'error', message: 'Gagal memproses review pengajuan CPD.' });
  }
});

// --- Rute GET /api/members/cpd/summary ---
// Mengambil ringkasan total poin CPD (Akumulasi Event APMA + Pengajuan Mandiri yang Approved)
app.get('/api/members/cpd/summary', async (req, res) => {
  try {
    const userId = Number(req.query.user_id) || 1;
    const currentYear = new Date().getFullYear();
    let totalPoints = 0;
    let eventPoints = 0;
    let submittedPoints = 0;

    try {
      // 1. Poin dari Event Internal APMA (Attended)
      const [eventRows] = await db.execute(
        `SELECT COALESCE(SUM(e.cpd_points), 0) AS total_points
         FROM event_registrations er
         JOIN events e ON er.event_id = e.event_id
         WHERE er.user_id = ?
           AND er.attendance_status = 'Attended'
           AND YEAR(e.event_date) = ?`,
        [userId, currentYear]
      );
      eventPoints = Number(eventRows[0]?.total_points || 0);

      // 2. Poin dari Pengajuan Mandiri Eksternal (Approved)
      const [subRows] = await db.execute(
        `SELECT COALESCE(SUM(approved_points), 0) AS sub_points
         FROM cpd_submissions
         WHERE user_id = ?
           AND status = 'Approved'
           AND YEAR(event_date) = ?`,
        [userId, currentYear]
      );
      submittedPoints = Number(subRows[0]?.sub_points || 0);

      totalPoints = eventPoints + submittedPoints;
    } catch (dbError) {
      console.warn('Database offline/query fallback:', dbError.message);
      // Fallback hitung dari mock in-memory
      const approvedSubs = mockCpdSubmissions.filter(s => s.user_id === userId && s.status === 'Approved');
      submittedPoints = approvedSubs.reduce((acc, curr) => acc + (curr.approved_points || 0), 0);
      eventPoints = 10; // Demo base points dari event
      totalPoints = eventPoints + submittedPoints;
    }

    const targetPoints = 30;

