// --- 12. Rute POST /api/admin/cpd/grant (Input Poin CPD Manual Langsung oleh Admin) ---
app.post('/api/admin/cpd/grant', async (req, res) => {
  try {
    const { user_id, event_name, provider_name, event_date, points, score, admin_notes, admin_id } = req.body;

    const userId = Number(user_id);
    const parsedPoints = parseInt(points, 10);

    if (!userId || !event_name || isNaN(parsedPoints) || parsedPoints <= 0) {
      return res.status(400).json({
        status: 'error',
        message: 'Anggota penerima, nama kegiatan/alasan, dan jumlah poin valid (> 0) wajib diisi.'
      });
    }

    // Ambil identitas anggota penerima
    let memberName = 'Anggota APMA';
    let memberIdNum = 'APMA-2026-0892';
    const foundMember = mockDirectoryMembers.find(m => m.id === userId);
    if (foundMember) {
      memberName = foundMember.name;
      memberIdNum = foundMember.member_id;
    }

    const eventDate = event_date || new Date().toISOString().substring(0, 10);
    const provider = provider_name || 'DPP APMA';
    const parsedScore = score ? parseFloat(score) : null;
    const nowStr = new Date().toISOString().replace('T', ' ').substring(0, 19);
    const notes = admin_notes || 'Pemberian Poin CPD Langsung oleh Admin (Penghargaan/Kontribusi Kegiatan)';
    const adminId = admin_id || 1;

    const newGrant = {
      submission_id: mockCpdSubmissions.length + 1,
      user_id: userId,
      user_name: memberName,
      member_id_number: memberIdNum,
      event_name,
      provider_name: provider,
      event_date: eventDate,
      score: parsedScore,
      claimed_points: parsedPoints,
      approved_points: parsedPoints,
      certificate_url: '/uploads/cert-official-apma.pdf',
      status: 'Approved',
      admin_notes: notes,
      submitted_at: nowStr,
      approved_at: nowStr,
      approved_by: adminId
    };

    mockCpdSubmissions.unshift(newGrant);

    // Coba simpan ke MySQL jika aktif
    try {
      const [userRows] = await db.execute('SELECT full_name, member_id_number FROM users_membership WHERE id = ?', [userId]);
      if (userRows && userRows.length > 0) {
        newGrant.user_name = userRows[0].full_name;
        newGrant.member_id_number = userRows[0].member_id_number;
      }

      await db.execute(
        `INSERT INTO cpd_submissions 
          (user_id, event_name, provider_name, event_date, score, claimed_points, approved_points, certificate_url, status, admin_notes, submitted_at, approved_at, approved_by)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?, 'Approved', ?, NOW(), NOW(), ?)`,
        [userId, event_name, provider, eventDate, parsedScore, parsedPoints, parsedPoints, '/uploads/cert-official-apma.pdf', notes, adminId]
      );
    } catch (dbErr) {
      console.warn('DB cpd grant fallback:', dbErr.message);
    }

    res.status(201).json({
      status: 'success',
      message: `Berhasil memberikan +${parsedPoints} Poin CPD langsung kepada ${newGrant.user_name}.`,
      data: newGrant
    });
  } catch (error) {
    console.error('Error granting CPD points:', error);
    res.status(500).json({ status: 'error', message: 'Gagal memproses input poin CPD manual.' });
  }
});

