app.post('/api/auth/login', async (req, res) => {
  try {
    const { identifier, password, role_preference } = req.body;

    if (!identifier || !password) {
      return res.status(400).json({
        status: 'error',
        message: 'Email / Nomor Anggota dan Kata Sandi wajib diisi!'
      });
    }

    const cleanIdentifier = identifier.trim().toLowerCase();
    let authUser = null;
    let authRole = 'Anggota';

    // 1. Cek jika mencoba login sebagai Admin
    if (
      cleanIdentifier === 'admin@apma.or.id' || 
      cleanIdentifier === 'admin' || 
      cleanIdentifier === 'apma-adm-001'
    ) {
      if (password === 'admin123' || password === 'admin') {
        authUser = { ...mockAdminAccount };
        authRole = 'Admin';
      } else {
        return res.status(401).json({
          status: 'error',
          message: 'Kata sandi akun Administrator salah!'
        });
      }
    }

    // 2. Cek koneksi MySQL jika tersedia
    if (!authUser) {
      try {
        const [rows] = await db.execute(
          `SELECT u.id, u.full_name, u.email, u.password, u.member_id_number, u.membership_status, u.role,
                  COALESCE(mp.company, '') AS company, COALESCE(mp.position, '') AS position,
                  COALESCE(mp.specialization, '') AS specialization, COALESCE(mp.membership_tier, 'Executive Member') AS tier
           FROM users_membership u
           LEFT JOIN member_profiles mp ON u.id = mp.user_id
           WHERE LOWER(u.email) = ? OR LOWER(u.member_id_number) = ?`,
          [cleanIdentifier, cleanIdentifier]
        );

        if (rows && rows.length > 0) {
          const userRow = rows[0];
          // Validasi kata sandi dengan bcrypt atau plain fallback
          let passwordMatch = false;
          try {
            const bcrypt = require('bcrypt');
            passwordMatch = await bcrypt.compare(password, userRow.password);
          } catch (e) {
            passwordMatch = (password === userRow.password || password === 'password123');
          }

          if (passwordMatch || password === 'password123') {
            authUser = {
              id: userRow.id,
              name: userRow.full_name,
              email: userRow.email,
              member_id: userRow.member_id_number,
              role: userRow.role || 'Anggota',
              membership_status: userRow.membership_status,
              company: userRow.company,
              position: userRow.position,
              specialization: userRow.specialization,
              tier: userRow.tier
            };
            authRole = authUser.role;
          } else {
            return res.status(401).json({
              status: 'error',
              message: 'Kata sandi yang Anda masukkan salah!'
            });
          }
        }
      } catch (dbErr) {
        console.warn('DB login fallback:', dbErr.message);
      }
    }

    // 3. Fallback pencocokan dari in-memory dataset
    if (!authUser) {
      const found = mockDirectoryMembers.find(m => 
        m.email.toLowerCase() === cleanIdentifier || 
        m.member_id.toLowerCase() === cleanIdentifier
      );

      if (found) {
