    const token = `apma_token_${authUser.id}_${Date.now()}`;
    const redirectUrl = (authUser.role === 'Admin' || role_preference === 'Admin') 
      ? 'admin_dashboard.html' 
      : 'member_dashboard.html';

    return res.status(200).json({
      status: 'success',
