// --- Rute GET /api/admin/members (Daftar Seluruh Anggota Lengkap dengan Search & Filter) ---
app.get('/api/admin/members', async (req, res) => {
  try {
    const { status, q, tier } = req.query;
    let list = [...mockDirectoryMembers];

    // Coba ambil langsung dari MySQL jika database aktif
    try {
      let query = `
        SELECT u.id, u.full_name AS name, u.email, u.member_id_number AS member_id, 
               u.membership_status, u.role, u.created_at,
               COALESCE(mp.headline, '') AS headline,
               COALESCE(mp.company, 'Anggota APMA') AS company,
               COALESCE(mp.position, 'Praktisi Pemasaran') AS position,
               COALESCE(mp.specialization, 'General Marketing') AS specialization,
               COALESCE(mp.location, 'Indonesia') AS location,
               COALESCE(mp.phone, '-') AS phone,
               COALESCE(mp.linkedin_url, '') AS linkedin,
               COALESCE(mp.avatar_url, '') AS avatar,
               COALESCE(mp.membership_tier, 'Executive Member') AS tier,
               COALESCE(mp.bio, '') AS bio,
               COALESCE(mp.open_for_collab, 1) AS open_for_collab
        FROM users_membership u
        LEFT JOIN member_profiles mp ON u.id = mp.user_id
        WHERE 1=1
      `;
      let params = [];

      if (status && status !== 'Semua' && status !== 'All') {
        query += ' AND u.membership_status = ?';
        params.push(status);
      }
      if (q) {
        query += ' AND (u.full_name LIKE ? OR u.email LIKE ? OR u.member_id_number LIKE ? OR mp.company LIKE ?)';
        const likeQ = `%${q}%`;
        params.push(likeQ, likeQ, likeQ, likeQ);
      }
      query += ' ORDER BY u.created_at DESC, u.id DESC';

      const [rows] = await db.execute(query, params);
      if (rows && rows.length > 0) list = rows;
    } catch (dbErr) {
      console.warn('DB admin members fallback:', dbErr.message);

      // Filter in-memory
      if (status && status !== 'Semua' && status !== 'All') {
        list = list.filter(m => m.membership_status.toLowerCase() === status.toLowerCase());
      }
      if (q) {
        const queryLower = q.toLowerCase();
        list = list.filter(m => 
          m.name.toLowerCase().includes(queryLower) ||
          m.email.toLowerCase().includes(queryLower) ||
          m.member_id.toLowerCase().includes(queryLower) ||
          m.company.toLowerCase().includes(queryLower) ||
          (m.specialization && m.specialization.toLowerCase().includes(queryLower))
        );
      }
    }

    // Hitung statistik ringkas status anggota
    const totalAll = mockDirectoryMembers.length;
    const totalPending = mockDirectoryMembers.filter(m => m.membership_status === 'Pending').length;
    const totalActive = mockDirectoryMembers.filter(m => m.membership_status === 'Active').length;
    const totalSuspended = mockDirectoryMembers.filter(m => m.membership_status === 'Suspended').length;

    res.status(200).json({
      status: 'success',
      counts: {
        all: totalAll,
        pending: totalPending,
        active: totalActive,
        suspended: totalSuspended
      },
      total: list.length,
      data: list
    });
  } catch (error) {
    console.error('Error fetching admin members:', error);
    res.status(500).json({ status: 'error', message: 'Gagal memuat data anggota untuk admin.' });
  }
});

