// --- Rute POST /api/admin/members (Tambah Anggota Baru oleh Admin Langsung) ---
app.post('/api/admin/members', async (req, res) => {
  try {
    const {
      full_name, email, phone, company, position, specialization,
      location, tier, membership_status, bio
    } = req.body;

    if (!full_name || !email) {
      return res.status(400).json({
        status: 'error',
        message: 'Nama lengkap dan Email anggota wajib diisi!'
      });
    }

    // Auto-generate Nomor Anggota: APMA-2026-XXXX
    const randomSuffix = Math.floor(1000 + Math.random() * 9000);
    const newMemberIdNumber = `APMA-2026-${randomSuffix}`;
    const newId = mockDirectoryMembers.length + 1;
    const nowStr = new Date().toISOString().replace('T', ' ').substring(0, 19);

    const newMember = {
      id: newId,
      name: full_name,
      email: email,
      member_id: newMemberIdNumber,
      role: 'Anggota',
      membership_status: membership_status || 'Active',
      position: position || 'Marketing Specialist',
      company: company || 'Independen / Agensi',
      specialization: specialization || 'Performance Marketing',
      location: location || 'DKI Jakarta',
      tier: tier || 'Executive Member',
      open_for_collab: true,
      avatar: 'https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?w=300&auto=format&fit=crop&q=80',
      bio: bio || 'Anggota terdaftar resmi Asosiasi Profesi Marketing Asuransi.',
      phone: phone || '+62 812-0000-0000',
      linkedin: 'https://linkedin.com',
      created_at: nowStr
    };

    mockDirectoryMembers.unshift(newMember);

    // Coba simpan ke MySQL jika database aktif
    try {
      const bcrypt = require('bcrypt');
      const hashedPassword = await bcrypt.hash('password123', 10);

      const [userResult] = await db.execute(
        `INSERT INTO users_membership (full_name, email, password, member_id_number, membership_status, role)
         VALUES (?, ?, ?, ?, ?, 'Anggota')`,
        [full_name, email, hashedPassword, newMemberIdNumber, newMember.membership_status]
      );

      const insertedUserId = userResult.insertId;
      newMember.id = insertedUserId;

      await db.execute(
        `INSERT INTO member_profiles (user_id, headline, company, position, specialization, location, phone, bio, membership_tier, membership_expiry)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, DATE_ADD(NOW(), INTERVAL 1 YEAR))`,
        [
          insertedUserId,
          `${position || 'Praktisi Pemasaran'} di ${company || 'APMA'}`,
          company || 'Independen',
          position || 'Marketing Specialist',
          specialization || 'Performance Marketing',
          location || 'DKI Jakarta',
          phone || '-',
          bio || '',
          newMember.tier
        ]
      );

      // Jalankan fungsi otomatisasi audit & email sambutan
      await onAfterAdminInsertMember(insertedUserId, 'Admin Master');
    } catch (dbErr) {
      console.warn('DB insert member fallback:', dbErr.message);
    }

    res.status(201).json({
      status: 'success',
      message: `Anggota baru ${newMember.name} (${newMember.member_id}) berhasil didaftarkan!`,
      data: newMember
    });
  } catch (error) {
    console.error('Error creating member by admin:', error);
    res.status(500).json({ status: 'error', message: 'Gagal menambahkan anggota baru.' });
  }
});

// --- Rute PUT /api/admin/members/:id/status (Verifikasi, Aktivasi, atau Suspend Anggota) ---
app.put('/api/admin/members/:id/status', async (req, res) => {
  try {
    const memberId = Number(req.params.id);
    const { status, admin_notes } = req.body;

    if (!['Active', 'Pending', 'Suspended'].includes(status)) {
      return res.status(400).json({
        status: 'error',
        message: 'Status harus bernilai Active, Pending, atau Suspended.'
      });
    }

    const member = mockDirectoryMembers.find(m => m.id === memberId);
    if (member) {
      member.membership_status = status;
    }

    // Update ke MySQL jika aktif
    try {
      await db.execute(
        'UPDATE users_membership SET membership_status = ? WHERE id = ?',
        [status, memberId]
      );
    } catch (dbErr) {
      console.warn('DB update member status fallback:', dbErr.message);
    }

    let statusTextIndo = 'diaktifkan';
    if (status === 'Pending') statusTextIndo = 'disetel menunggu verifikasi';
    if (status === 'Suspended') statusTextIndo = 'ditangguhkan (Suspended)';

    res.status(200).json({
      status: 'success',
      message: `Status keanggotaan berhasil ${statusTextIndo}.`,
      data: { member_id: memberId, status: status }
    });
  } catch (error) {
    console.error('Error updating member status:', error);
    res.status(500).json({ status: 'error', message: 'Gagal memperbarui status anggota.' });
  }
});

// --- Rute PUT /api/admin/members/:id (Edit Profil Lengkap Anggota oleh Admin) ---
app.put('/api/admin/members/:id', async (req, res) => {
  try {
    const memberId = Number(req.params.id);
    const {
      name, email, company, position, specialization,
      location, phone, tier, membership_status, bio
    } = req.body;

    const member = mockDirectoryMembers.find(m => m.id === memberId);
    if (!member) {
      return res.status(404).json({ status: 'error', message: 'Anggota tidak ditemukan.' });
    }

    if (name) member.name = name;
    if (email) member.email = email;
    if (company) member.company = company;
    if (position) member.position = position;
    if (specialization) member.specialization = specialization;
    if (location) member.location = location;
    if (phone) member.phone = phone;
    if (tier) member.tier = tier;
    if (membership_status) member.membership_status = membership_status;
    if (bio) member.bio = bio;

    // Update ke MySQL jika ada
    try {
      await db.execute(
        'UPDATE users_membership SET full_name = ?, email = ?, membership_status = ? WHERE id = ?',
        [member.name, member.email, member.membership_status, memberId]
      );
      await db.execute(
        `UPDATE member_profiles 
         SET company = ?, position = ?, specialization = ?, location = ?, phone = ?, bio = ?, membership_tier = ?
         WHERE user_id = ?`,
        [member.company, member.position, member.specialization, member.location, member.phone, member.bio, member.tier, memberId]
      );
    } catch (dbErr) {
      console.warn('DB update member details fallback:', dbErr.message);
    }

    res.status(200).json({
      status: 'success',
      message: `Data anggota ${member.name} berhasil diperbarui!`,
      data: member
    });
  } catch (error) {
    console.error('Error updating member details:', error);
    res.status(500).json({ status: 'error', message: 'Gagal memperbarui data anggota.' });
  }
});

// --- Rute DELETE /api/admin/members/:id (Hapus Anggota) ---
app.delete('/api/admin/members/:id', async (req, res) => {
  try {
    const memberId = Number(req.params.id);
    const index = mockDirectoryMembers.findIndex(m => m.id === memberId);

    if (index === -1) {
      return res.status(404).json({ status: 'error', message: 'Anggota tidak ditemukan.' });
    }

    const deletedMember = mockDirectoryMembers.splice(index, 1)[0];

    // Hapus dari MySQL jika ada
    try {
      await db.execute('DELETE FROM users_membership WHERE id = ?', [memberId]);
    } catch (dbErr) {
      console.warn('DB delete member fallback:', dbErr.message);
    }

    res.status(200).json({
      status: 'success',
      message: `Data anggota ${deletedMember.name} (${deletedMember.member_id}) berhasil dihapus.`
    });
  } catch (error) {
    console.error('Error deleting member:', error);
    res.status(500).json({ status: 'error', message: 'Gagal menghapus data anggota.' });
  }
});

